await fs.mkdir(CAP, { recursive: true });

const TEXT_MIME = ["html", "css", "javascript", "ecmascript", "json", "manifest", "text/plain", "xml"];
const TEXT_EXT = /\.(js|mjs|cjs|jsx|ts|tsx|css|html?|json|webmanifest|map|txt|xml)(\?|$)/;

function isText(mime, url) {
  const m = (mime || "").toLowerCase();
  const p = new URL(url).pathname.toLowerCase();
  return TEXT_MIME.some(x => m.includes(x)) || TEXT_EXT.test(p);
}

// 落盘路径：host/path，保留 query 的哈希后缀，避免不同 ?id= 的响应互相覆盖
function safeLocal(url) {
  const u = new URL(url);
  let p = decodeURIComponent(u.pathname).replace(/\\/g, "/");
  p = p.replace(/\.\./g, "__").replace(/[^A-Za-z0-9._\-\/]/g, "_");
  if (p.endsWith("/")) p += "index.html";
  if (!path.extname(p)) p += "/index.html";
  if (u.search) {
    const h = crypto.createHash("sha1").update(u.search).digest("hex").slice(0, 8);
    const ext = path.extname(p);
    p = (ext ? p.slice(0, -ext.length) : p) + "__q" + h + ext;
  }
  return path.join(OUT, "mirror", u.host.replace(/[^A-Za-z0-9._\-]/g, "_"), p.replace(/^\//, ""));
}

